<?php declare(strict_types=1);namespace NpmGateway\Services;use NpmGateway\Contracts\{ClockInterface,InitializationTransactionInterface};use NpmGateway\Notifications\SupplyOrderEmailSender;use NpmGateway\Repositories\SupplyOrderRepository;use NpmGateway\Support\PublicIdGenerator;use NpmGateway\ValueObjects\{AuthenticatedUser,CommunityActionContext};
final readonly class SupplyOrderService{public function __construct(private SupplyOrderRepository$repo,private SupplyOrderValidator$validator,private InitializationTransactionInterface$tx,private PublicIdGenerator$ids,private ClockInterface$clock,private AuditService$audit,private SupplyOrderEmailSender$mail){}
 public function listForProperty(int$propertyId):array{return$this->repo->list($propertyId);}
 public function detailForProperty(string$publicId,int$propertyId):?array{return$this->repo->detail($publicId,$propertyId);}
 public function submit(CommunityActionContext$context,array$input):array{$data=$this->validator->validate($input);$public=$this->ids->generate();$at=$this->clock->now()->format('Y-m-d H:i:s');$this->tx->begin();try{$this->repo->insert(['public_id'=>$public,'property_id'=>$context->propertyId,'actor_id'=>$context->userId,'submitted_at'=>$at]+$data);$this->audit->record('supply_order.submitted',$context->userId,$context->employeeId,$context->userPublicId,'Supply order submitted.',['supply_order_public_id'=>$public,'property_public_id'=>$context->propertyPublicId],$at);$this->tx->commit();}catch(\Throwable$e){$this->tx->rollback();throw$e;}$order=$this->repo->detail($public,$context->propertyId);return['public_id'=>$public,'email_sent'=>$order!==null&&$this->mail->submitted($order)];}
}
